import { quotation_sub_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    itemdeletion: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    itemdeletion: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(quotation_sub_categories, {
          input: {
            action_type: "DELETE",
            sub_category_id: this.rowInfo.sub_category_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.quotation_sub_categories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
